typedef unsigned int size_t;
#define NULL 0
#define NEW new

void *operator new(size_t);

class stringx {
    char *chars;
    void *buffer;
public:
    stringx(const char *, int = -1);
    stringx(const stringx &);
    ~stringx();
};

class Font {
public:
    enum HORIZJUST { HORIZJUST_CENTER };
    enum VERTJUST { VERTJUST_CENTER };
};

class color32 {
public:
    unsigned int value;
};

class TextString {
public:
    TextString(Font *, stringx, float, float, float, float,
               Font::HORIZJUST, Font::VERTJUST, color32);
    void changePos(float, float);
};

class FEMenuSystem;

class FEManager {
public:
    Font font_info;
    Font font_bold;
    color32 col_highlight2;
};

class FEMenuEntry;

class FEMenu {
public:
    int center_x;
    int center_y;
    int num_entries;
    int dy;
    int half;
    int menu_num;
    bool init;
    char init_padding[3];
    stringx font_filename;
    color32 color;
    color32 color_high;
    color32 color_high_alt;
    float scale;
    float scale_high;
    int max_vis_entries;
    int flags;
    FEMenuEntry *entries;
    FEMenuEntry *first_vis_entry;
    FEMenuEntry *last_vis_entry;
    FEMenuEntry *highlighted;
    FEMenuSystem *system;
    FEMenu *back;
    int back_num;
protected:
    FEMenu *submenus;
    FEMenu *active;
    FEMenu *parent;
    TextString *helpText;
    int helpFlags;
public:
    FEMenu *next_sub;
    virtual ~FEMenu();
    virtual void SetHelpText(int);
};

class PanelAnimManager {
    char data[0x80];
};

class PanelFile {
    char data[0x30];
};

class FrontEnd {
public:
    PanelAnimManager pam;
    PanelFile panel;
    FrontEnd *next;
    stringx path;
    FEManager *manager;
    virtual ~FrontEnd();
};

class FEGraphicalMenu : public FEMenu, public FrontEnd {
protected:
    virtual void cons(FEMenuSystem *, FEManager *, stringx, stringx);
};

class FEMultiMenu : public FEGraphicalMenu {
public:
    FEMenuEntry *first;
    FEMenuEntry *last;
    FEMultiMenu();
protected:
    virtual void cons(FEMenuSystem *, FEManager *, stringx, stringx);
};

class PhotoWidget {
    char layout[0x10c];
};

class PhotoDevelopMenu : public FEMultiMenu {
private:
    TextString *title;
    PhotoWidget photo;
    int *whichPhotoPtr;
    bool doneCompressing;
    int drawCounter;
public:
    PhotoDevelopMenu(FEMenuSystem *s, FEManager *man);
};

extern stringx ksGlobalTextArray[];

enum {
    FEMENU_1_ENTRY_SHOWN = 1,
    FEMENU_DONT_SKIP_DISABLED = 2,
    GT_PHOTO_COMPRESS = 0
};

PhotoDevelopMenu::PhotoDevelopMenu(FEMenuSystem* s, FEManager* man)
{
    Font *font;
    stringx str;

    cons(s, man, "", "");
    flags |= FEMENU_1_ENTRY_SHOWN | FEMENU_DONT_SKIP_DISABLED;
    font = &man->font_info;

    title = NULL;

    title = NEW TextString(&manager->font_bold, ksGlobalTextArray[GT_PHOTO_COMPRESS], 320, 75, 100, 1.0f, Font::HORIZJUST_CENTER, Font::VERTJUST_CENTER, man->col_highlight2);
    SetHelpText(0);
    helpText->changePos(320, 424);
    doneCompressing = false;
    drawCounter = 0;
}
